# 5) GroupChatScreen.kt — call site + real-time event handler
# ---------------------------------------------------------------------------
apply(
    "app/src/main/java/com/muwan/muwanchat/screens/GroupChatScreen.kt",
'''            val res = RetrofitClient.chatApi.getMessages("Bearer $token", groupId)
            if (res.isSuccessful) {
