SETTINGS = "app/src/main/java/com/muwan/muwanchat/screens/SettingsScreen.kt"

# ---------------------------------------------------------------------------
# 1) NavGraph.kt: add 3 new routes
# ---------------------------------------------------------------------------
apply(
    NAVGRAPH,
    '''    object Login           : Screen("login")
    object Register        : Screen("register")''',
    '''    object Login           : Screen("login")
    object Register        : Screen("register")
    object TermsPolicy     : Screen("terms_policy")
    object TermsPrivacy    : Screen("terms_privacy")
    object ApplicationRules : Screen("application_rules")''',
    "NavGraph: add TermsPolicy/TermsPrivacy/ApplicationRules routes",
)

# ---------------------------------------------------------------------------
# 2) NavGraph.kt: register the 3 new composables
# ---------------------------------------------------------------------------
apply(
    NAVGRAPH,
    '''        composable(Screen.Login.route) { LoginScreen(navController) }
        composable(Screen.Register.route) { RegisterScreen(navController) }''',
    '''        composable(Screen.Login.route) { LoginScreen(navController) }
        composable(Screen.Register.route) { RegisterScreen(navController) }
        composable(Screen.TermsPolicy.route) { TermsPolicyScreen(navController) }
        composable(Screen.TermsPrivacy.route) { TermsPrivacyScreen(navController) }
        composable(Screen.ApplicationRules.route) { ApplicationRulesScreen(navController) }''',
    "NavGraph: register 3 new composables",
)

# ---------------------------------------------------------------------------
# 3) SplashScreen.kt: brand-new (no session) users -> Register instead of Login
# ---------------------------------------------------------------------------
apply(
    SPLASH,
    '''        } else {
            navController.navigate(Screen.Login.route) {
                popUpTo(Screen.Splash.route) { inclusive = true }
            }
        }''',
    '''        } else {
            navController.navigate(Screen.Register.route) {
                popUpTo(Screen.Splash.route) { inclusive = true }
            }
        }''',
    "SplashScreen: cold-start default -> Register",
)

# ---------------------------------------------------------------------------
# 4) RegisterScreen.kt: after successful register -> TermsPolicy (not Profile)
# ---------------------------------------------------------------------------
apply(
    REGISTER,
    '''                    navController.navigate(Screen.Profile.createRoute("onboarding")) {
                        popUpTo(Screen.Register.route) { inclusive = true }
                    }
                } else {''',
    '''                    navController.navigate(Screen.TermsPolicy.route) {
                        popUpTo(Screen.Register.route) { inclusive = true }
                    }
                } else {''',
    "RegisterScreen: route to TermsPolicy after signup",
)

# ---------------------------------------------------------------------------
# 5) SettingsScreen.kt: add 2 new rows before Logout
# ---------------------------------------------------------------------------
apply(
    SETTINGS,
    '''        Divider(color = Color(0xFF1E2040), thickness = 0.5.dp)

        Spacer(modifier = Modifier.height(8.dp))

        // 4. Logout''',
    '''        Divider(color = Color(0xFF1E2040), thickness = 0.5.dp)

        Spacer(modifier = Modifier.height(8.dp))

        // 3.6 Terms & Privacy Policy
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .clickable { navController.navigate(Screen.TermsPrivacy.route) }
                .padding(horizontal = 16.dp, vertical = 16.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(Icons.Filled.Policy, contentDescription = "Terms & Privacy Policy", tint = Color.White)
            Spacer(modifier = Modifier.width(16.dp))
            Text("Terms & Privacy Policy", color = Color.White, fontSize = 16.sp, modifier = Modifier.weight(1f))
            Icon(Icons.Filled.ChevronRight, contentDescription = null, tint = Color(0xFF888888))
        }
        Divider(color = Color(0xFF1E2040), thickness = 0.5.dp)

        // 3.7 Application Laws & Rules
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .clickable { navController.navigate(Screen.ApplicationRules.route) }
                .padding(horizontal = 16.dp, vertical = 16.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(Icons.Filled.Gavel, contentDescription = "Application Laws & Rules", tint = Color.White)
            Spacer(modifier = Modifier.width(16.dp))
            Text("Application Laws & Rules", color = Color.White, fontSize = 16.sp, modifier = Modifier.weight(1f))
            Icon(Icons.Filled.ChevronRight, contentDescription = null, tint = Color(0xFF888888))
        }
        Divider(color = Color(0xFF1E2040), thickness = 0.5.dp)

        Spacer(modifier = Modifier.height(8.dp))

        // 4. Logout''',
    "SettingsScreen: add Terms & Privacy / Application Rules rows",
)

print("\\nAll patches applied successfully.")


# ===========================================================================
# SOURCE FILE: rename_login_register.sh
# ===========================================================================
#!/data/data/com.termux/files/usr/bin/bash
set -e

LOGIN="app/src/main/java/com/muwan/muwanchat/screens/LoginScreen.kt"
REGISTER="app/src/main/java/com/muwan/muwanchat/screens/RegisterScreen.kt"

if [ ! -f "$LOGIN" ] || [ ! -f "$REGISTER" ]; then
  echo "ERROR: run this from project root (where app/ folder is)"
  exit 1
fi

sed -i 's/Text("M", fontSize = 64.sp, fontWeight = FontWeight.Bold, color = DarkAccent)/Text("T", fontSize = 64.sp, fontWeight = FontWeight.Bold, color = DarkAccent)/' "$LOGIN"
sed -i 's/Text("MuwanChat", fontSize = 24.sp, fontWeight = FontWeight.Bold, color = Color.White)/Text("TalkWave", fontSize = 24.sp, fontWeight = FontWeight.Bold, color = Color.White)/' "$LOGIN"

sed -i 's/Text("M", color = DarkAccent, fontSize = 60.sp, fontWeight = FontWeight.Bold)/Text("T", color = DarkAccent, fontSize = 60.sp, fontWeight = FontWeight.Bold)/' "$REGISTER"
sed -i 's/Text("MuwanChat", color = Color.White, fontSize = 24.sp, fontWeight = FontWeight.Bold)/Text("TalkWave", color = Color.White, fontSize = 24.sp, fontWeight = FontWeight.Bold)/' "$REGISTER"

echo "Done: M -> T and MuwanChat -> TalkWave updated in Login & Register screens."


# ===========================================================================
# SOURCE FILE: revert_mentions_patch.py
# ===========================================================================
def patch(path, old, new, label):
    with open(path, encoding='utf-8') as f:
        s = f.read()
    if old not in s and new in s:
        print(f"[skip] {label} (already reverted)")
        return
    assert old in s, f"[FAIL] pattern not found for: {label} in {path}"
    s = s.replace(old, new, 1)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(s)
    print(f"[ok] reverted: {label}")

BASE = "app/src/main/java/com/muwan/muwanchat"

patch(f"{BASE}/network/ChatApi.kt",
    "    val is_forwarded: Boolean = false,\n"
    "    val mentions: List<String>? = null\n"
    ")",
    "    val is_forwarded: Boolean = false\n"
    ")",
    "MessageItem.mentions field")

patch(f"{BASE}/screens/ChatMessage.kt",
    "    val isForwarded: Boolean = false,\n"
    "    val mentions: List<String> = emptyList()\n"
    ")",
    "    val isForwarded: Boolean = false\n"
    ")",
    "ChatMessage.mentions field")

patch(f"{BASE}/screens/ChatMessage.kt",
    "    isForwarded = is_forwarded,\n"
    "    mentions = mentions ?: emptyList()\n"
    ")",
    "    isForwarded = is_forwarded\n"
    ")",
    "MessageItem.toChatMessage mentions mapping")

patch(f"{BASE}/screens/ChatMessage.kt",
    "    isForwarded = isForwarded,\n"
    "    mentions = mentions?.split(\",\")?.filter { it.isNotBlank() } ?: emptyList()\n"
    ")",
    "    isForwarded = isForwarded\n"
    ")",
    "MessageEntity.toChatMessage mentions mapping")

patch(f"{BASE}/data/MessageEntity.kt",
    "    val previewUrl: String? = null,\n"
    "    val mentions: String? = null   // comma-separated uids jinhe is message mein mention kiya gaya\n"
    ")",
    "    val previewUrl: String? = null\n"
    ")",
    "MessageEntity.mentions column")

import os
if os.path.exists("patch_part1.py"):
    os.remove("patch_part1.py")
    print("[ok] removed: patch_part1.py (no longer needed)")
else:
    print("[skip] patch_part1.py already removed")

print("\nRevert done. Adhura 'mentions' feature completely hat gaya.")
print("NOTE: DB version (22) jaanbujh kar nahi chheda -- agar is device pe pehle se")
print("v22 wali DB bani hui hai (mentions column ke saath), naya build install karne")
print("se pehle app UNINSTALL ya clear data kar lena, warna Room data-integrity crash dega.")


